create table d_trd_bundle_info(bundle_id string comment '组合编号',key_plan_id string comment '履保方案id',bundle_type string comment '组合类型',bundle_audit_status string comment '组合审计状态',key_ctpty_id string comment '交易对手id',option_day_count string comment '期权计息日基准',option_payment_calendar string comment '期权支付日日历',option_deferral_type string comment '期权递延方式',created_by string comment '创建人',updated_by string comment '修改人',created_datetime string comment '创建时间',updated_datetime string comment '修改时间',data_time string comment '【AI】数据时间',sec_collateral_bundle string comment '【券抵组合】开关',trs_fund_is_include_short string comment '多头基金包含空头持仓-默认N',mtm_currency string comment '盯市币种',department string comment '部门') partitioned by (busi_date string) row format delimited fields terminated by ',' stored as textfile;
